// Agente Orquestrador - Inicialização
// Este agente coordena todos os sub-agentes especializados

const timestamp = new Date().toISOString();
const sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

return [{
  json: {
    sessionId: sessionId,
    timestamp: timestamp,
    orchestrator: {
      name: 'Agente Orquestrador CredGestor',
      version: '1.0',
      role: 'Coordenação e distribuição de tarefas para sub-agentes especializados'
    },
    status: 'initializing',
    agents: {
      infra: { status: 'pending', called: false },
      developer: { status: 'pending', called: false },
      database: { status: 'pending', called: false }
    }
  }
}];

// Agente Orquestrador - Análise Inicial
// Coleta dados e prepara para análise com Claude AI

const orchestratorData = $('Inicializar Orquestrador').item.json;
const healthApi = $('Health Check API').item.json;
const metrics = $('Verificar Métricas').item.json;
const frontend = $('Health Check Frontend').item.json;
const dbConnections = $('Verificar Conexões DB').item.json[0] || {};

const timestamp = new Date().toISOString();

// Analisar status de cada componente
const analysis = {
  api: {
    status: healthApi.statusCode === 200 ? 'healthy' : 'unhealthy',
    statusCode: healthApi.statusCode,
    response: healthApi.body || {}
  },
  metrics: {
    status: metrics.statusCode === 200 ? 'available' : 'unavailable',
    hasData: metrics.statusCode === 200
  },
  frontend: {
    status: frontend.statusCode === 200 ? 'healthy' : 'unhealthy',
    statusCode: frontend.statusCode
  },
  database: {
    totalConnections: parseInt(dbConnections.total_connections || 0),
    activeConnections: parseInt(dbConnections.active_connections || 0),
    idleConnections: parseInt(dbConnections.idle_connections || 0),
    status: 'healthy'
  }
};

// Detectar problemas iniciais
const issues = [];

if (analysis.api.status === 'unhealthy' || analysis.metrics.status === 'unavailable') {
  issues.push({
    type: 'infrastructure',
    severity: 'critical',
    component: 'backend',
    message: `API ou métricas com problemas`
  });
}

if (analysis.database.totalConnections > 50 || analysis.database.activeConnections > 30) {
  issues.push({
    type: 'database',
    severity: 'warning',
    component: 'database',
    message: `Muitas conexões ativas: ${analysis.database.activeConnections}`
  });
}

if (analysis.frontend.status === 'unhealthy') {
  issues.push({
    type: 'frontend',
    severity: 'critical',
    component: 'frontend',
    message: `Frontend retornou status ${analysis.frontend.statusCode}`
  });
}

return [{
  json: {
    ...orchestratorData,
    analysis: analysis,
    issues: issues,
    readyForClaude: true
  }
}];

// Preparar prompt para Claude AI - Decisão do Orquestrador
const data = $input.item.json;

const prompt = `Você é o Agente Orquestrador do CredGestor, responsável por coordenar sub-agentes especializados em troubleshooting.

CONTEXTO DA APLICAÇÃO:
- Aplicação: CredGestor - Sistema de Gestão de Crédito Multi-Tenancy
- Stack: Frontend (React + Vite), Backend (FastAPI + Python 3.11)
- Infraestrutura: Docker Swarm, Traefik, Supabase (PostgreSQL)
- URLs: https://credgestor.app.br (Frontend), https://credgestor.app.br/api (Backend)

DADOS COLETADOS:
${JSON.stringify(data.analysis, null, 2)}

PROBLEMAS DETECTADOS:
${JSON.stringify(data.issues, null, 2)}

SUA TAREFA:
Analise os dados coletados e decida quais sub-agentes especializados devem ser chamados:
- Agente de Infraestrutura: Para problemas de Linux, Docker, Traefik, Rede
- Agente de Banco de Dados: Para problemas de PostgreSQL, queries, performance
- Agente de Desenvolvimento: Para problemas de código, frontend, backend, API

FORMATO DE RESPOSTA (JSON OBRIGATÓRIO):
{
  "agentsToCall": ["infra", "database", "developer"],
  "reasoning": "Explicação detalhada de por que cada agente foi escolhido",
  "priority": "high|medium|low",
  "estimatedTime": "tempo estimado para resolução"
}`;

return [{
  json: {
    ...data,
    prompt: prompt,
    model: $env.LLM_MODEL || 'claude-3-5-sonnet-20241022'
  }
}];

