// Processar decisão do Claude AI
const analysisData = $('Análise Inicial').item.json;
const llmResponse = $input.item.json;

// Extrair texto da resposta
let decisionText = '';
let responseBody = llmResponse.body || llmResponse;
if (typeof responseBody === 'string') {
  try {
    responseBody = JSON.parse(responseBody);
  } catch (e) {
    responseBody = { content: [{ type: 'text', text: responseBody }] };
  }
}

if (responseBody.content && Array.isArray(responseBody.content)) {
  const textContent = responseBody.content.find(c => c.type === 'text');
  decisionText = textContent ? textContent.text : JSON.stringify(responseBody.content);
} else {
  decisionText = JSON.stringify(responseBody);
}

// Parsear JSON da resposta
let agentsToCall = [];
let reasoning = 'Análise automática';
let priority = 'medium';

try {
  const jsonMatch = decisionText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    agentsToCall = parsed.agentsToCall || [];
    reasoning = parsed.reasoning || reasoning;
    priority = parsed.priority || priority;
  }
} catch (e) {
  // Fallback: decidir baseado em problemas detectados
  if (analysisData.issues.some(i => i.type === 'infrastructure')) agentsToCall.push('infra');
  if (analysisData.issues.some(i => i.type === 'database')) agentsToCall.push('database');
  if (analysisData.issues.some(i => i.type === 'frontend')) agentsToCall.push('developer');
}

// Remover duplicatas
const uniqueAgents = [...new Set(agentsToCall)];

return [{
  json: {
    ...analysisData,
    agentsToCall: uniqueAgents,
    decision: {
      timestamp: new Date().toISOString(),
      reasoning: reasoning,
      priority: priority,
      claudeDecision: true
    },
    status: analysisData.issues.length > 0 ? 'issues_detected' : 'healthy'
  }
}];

// Preparar chamada para cada sub-agente
const data = $input.item.json;
const agentsToCall = data.agentsToCall || [];

const agentCalls = agentsToCall.map(agentType => {
  const agentConfig = {
    infra: {
      workflowId: $env.WORKFLOW_AGENTE_INFRA_ID || 'agente-infra',
      name: 'Agente de Infraestrutura',
      endpoint: $env.WORKFLOW_AGENTE_INFRA_URL || 'http://localhost:5678/webhook/agente-infra'
    },
    developer: {
      workflowId: $env.WORKFLOW_AGENTE_DEV_ID || 'agente-dev',
      name: 'Agente de Desenvolvimento',
      endpoint: $env.WORKFLOW_AGENTE_DEV_URL || 'http://localhost:5678/webhook/agente-dev'
    },
    database: {
      workflowId: $env.WORKFLOW_AGENTE_DB_ID || 'agente-database',
      name: 'Agente de Banco de Dados',
      endpoint: $env.WORKFLOW_AGENTE_DB_URL || 'http://localhost:5678/webhook/agente-database'
    }
  };

  const config = agentConfig[agentType];
  if (!config) return null;

  return {
    agentType: agentType,
    agentName: config.name,
    endpoint: config.endpoint,
    workflowId: config.workflowId,
    payload: {
      sessionId: data.sessionId,
      timestamp: data.timestamp,
      orchestratorDecision: data.decision,
      issues: data.issues.filter(i => 
        (agentType === 'infra' && (i.type === 'infrastructure' || i.component === 'backend')) ||
        (agentType === 'developer' && (i.type === 'frontend' || i.component === 'frontend')) ||
        (agentType === 'database' && (i.type === 'database' || i.component === 'database'))
      ),
      context: {
        api: data.analysis.api,
        metrics: data.analysis.metrics,
        frontend: data.analysis.frontend,
        database: data.analysis.database
      }
    }
  };
}).filter(call => call !== null);

return agentCalls.map(call => ({ json: call }));

// Agregar respostas dos sub-agentes
const agentCall = $('Processar Chamadas').item.json;
const agentResponse = $input.item.json;

// Processar resposta do agente
let analysis = {};
if (agentResponse.body) {
  analysis = typeof agentResponse.body === 'string' 
    ? JSON.parse(agentResponse.body) 
    : agentResponse.body;
} else {
  analysis = agentResponse;
}

return [{
  json: {
    agentType: agentCall.agentType,
    agentName: agentCall.agentName,
    sessionId: agentCall.payload.sessionId,
    response: analysis,
    status: agentResponse.statusCode === 200 ? 'success' : 'error',
    timestamp: new Date().toISOString()
  }
}];

// Agente Orquestrador - Consolidar Resultados
// Consolida análises de todos os sub-agentes

const orchestratorData = $('Decisão do Orquestrador').item.json;
const agentResponses = $input.all();

const consolidatedAnalysis = {
  sessionId: orchestratorData.sessionId,
  timestamp: orchestratorData.timestamp,
  orchestrator: orchestratorData.orchestrator,
  issues: orchestratorData.issues,
  agentAnalyses: agentResponses.map(r => r.json),
  summary: {
    totalAgentsCalled: agentResponses.length,
    agentsWithIssues: agentResponses.filter(r => r.json.response && r.json.response.hasIssues).length,
    criticalIssues: orchestratorData.issues.filter(i => i.severity === 'critical').length,
    totalActions: agentResponses.reduce((sum, r) => {
      const actions = r.json.response?.actionPlan?.length || 0;
      return sum + actions;
    }, 0)
  },
  consolidatedActionPlan: agentResponses.reduce((plan, r) => {
    const actions = r.json.response?.actionPlan || [];
    return plan.concat(actions.map(a => ({
      ...a,
      agent: r.json.agentType,
      agentName: r.json.agentName
    })));
  }, []),
  requiresApproval: agentResponses.some(r => r.json.response?.requiresApproval === true)
};

return [{
  json: consolidatedAnalysis
}];

// Formatar mensagem de notificação consolidada com planos dos resolutores
const aggregated = $('Agregar Respostas Resolutores').item.json;
const consolidated = aggregated.troubleshooting;
const savedReport = aggregated.reportId;
const resolvers = aggregated.resolvers;

const severity = consolidated.issues.some(i => i.severity === 'critical') ? 'critical' : 'medium';
const severityEmoji = {
  'critical': '🔴',
  'high': '🟠',
  'medium': '🟡',
  'low': '🟢'
}[severity] || '⚪';

let message = `${severityEmoji} *ALERTA MULTI-AGENTE: Problema Detectado no CredGestor*\n\n`;
message += `*Agente Orquestrador* coordenou ${consolidated.summary.totalAgentsCalled} sub-agente(s) de troubleshooting\n`;
message += `*Severidade:* ${severity.toUpperCase()}\n`;
message += `*Data/Hora:* ${new Date(consolidated.timestamp).toLocaleString('pt-BR')}\n\n`;

message += `*📋 PROBLEMAS DETECTADOS:*\n`;
for (const issue of consolidated.issues) {
  message += `• ${issue.type}: ${issue.message} (${issue.severity})\n`;
}

message += `\n*🤖 ANÁLISES DOS SUB-AGENTES (TROUBLESHOOTING):*\n`;
for (const agentAnalysis of consolidated.agentAnalyses) {
  if (agentAnalysis.response && agentAnalysis.response.diagnosis) {
    const summary = agentAnalysis.response.diagnosis.summary || 'Análise concluída';
    message += `\n*${agentAnalysis.agentName}:*\n`;
    message += `${summary.substring(0, 200)}...\n`;
  }
}

message += `\n*📝 PLANO DE AÇÃO CONSOLIDADO:*\n`;
for (let i = 0; i < Math.min(consolidated.consolidatedActionPlan.length, 5); i++) {
  const action = consolidated.consolidatedActionPlan[i];
  message += `${i + 1}. [${action.agent}] ${action.description}\n`;
}
if (consolidated.consolidatedActionPlan.length > 5) {
  message += `... e mais ${consolidated.consolidatedActionPlan.length - 5} ações\n`;
}

message += `\n*🔧 PLANOS DE EXECUÇÃO DOS RESOLUTORES:*\n`;
for (const resolver of resolvers.resolvers) {
  if (resolver.response && resolver.response.executionPlan) {
    message += `\n*${resolver.resolverName}:*\n`;
    const plan = resolver.response.executionPlan;
    for (let i = 0; i < Math.min(plan.length, 3); i++) {
      message += `${i + 1}. ${plan[i].description}\n`;
    }
    if (plan.length > 3) {
      message += `... e mais ${plan.length - 3} ações\n`;
    }
    if (resolver.response.vpsConnection) {
      message += `\n📡 Instruções de conexão VPS incluídas no relatório\n`;
    }
  }
}

message += `\n*⚠️ AÇÕES REQUEREM APROVAÇÃO*\n`;
message += `ID do Relatório: ${savedReport || 'N/A'}\n\n`;

message += `*Para aprovar e executar:*\n`;
message += `Responda: APROVAR ${savedReport || 'REPORT_ID'}\n\n`;
message += `*Para rejeitar:*\n`;
message += `Responda: REJEITAR ${savedReport || 'REPORT_ID'}\n`;

return [{
  json: {
    message: message,
    reportId: savedReport,
    consolidated: consolidated,
    resolvers: resolvers,
    channel: '#credgestor-alerts',
    thread_ts: null
  }
}];

// Resumo final da execução do orquestrador
const consolidated = $('Consolidar Resultados').item.json;
const savedReport = $('Salvar Relatório Consolidado').item.json[0];

return [{
  json: {
    executionTime: new Date().toISOString(),
    sessionId: consolidated.sessionId,
    reportId: savedReport.id,
    orchestrator: consolidated.orchestrator,
    agentsCalled: consolidated.summary.totalAgentsCalled,
    issuesFound: consolidated.issues.length,
    actionsGenerated: consolidated.summary.totalActions,
    requiresApproval: consolidated.requiresApproval,
    status: 'completed'
  }
}];

// Preparar envio de plano de ação para agentes resolutores
const consolidated = $('Consolidar Resultados').item.json;
const savedReport = $('Salvar Relatório Consolidado').item.json[0];

// Agrupar ações por tipo de agente
const actionsByAgent = {
  infra: consolidated.consolidatedActionPlan.filter(a => a.agent === 'infra'),
  database: consolidated.consolidatedActionPlan.filter(a => a.agent === 'database'),
  developer: consolidated.consolidatedActionPlan.filter(a => a.agent === 'developer')
};

// Preparar chamadas para resolutores
const resolverCalls = [];

if (actionsByAgent.infra.length > 0) {
  resolverCalls.push({
    resolverType: 'infra',
    resolverName: 'Resolutor de Infraestrutura',
    endpoint: $env.WORKFLOW_RESOLUTOR_INFRA_URL || 'http://localhost:5678/webhook/resolutor-infra',
    payload: {
      troubleshootingSessionId: consolidated.sessionId,
      sessionId: `resolver_${Date.now()}_infra`,
      timestamp: new Date().toISOString(),
      actionPlan: actionsByAgent.infra,
      diagnosis: consolidated.agentAnalyses.find(a => a.agentType === 'infra')?.response?.diagnosis || {},
      issues: consolidated.issues.filter(i => i.type === 'infrastructure' || i.component === 'backend'),
      context: consolidated.agentAnalyses.find(a => a.agentType === 'infra')?.response || {}
    }
  });
}

if (actionsByAgent.database.length > 0) {
  resolverCalls.push({
    resolverType: 'database',
    resolverName: 'Resolutor de Banco de Dados',
    endpoint: $env.WORKFLOW_RESOLUTOR_DB_URL || 'http://localhost:5678/webhook/resolutor-database',
    payload: {
      troubleshootingSessionId: consolidated.sessionId,
      sessionId: `resolver_${Date.now()}_database`,
      timestamp: new Date().toISOString(),
      actionPlan: actionsByAgent.database,
      diagnosis: consolidated.agentAnalyses.find(a => a.agentType === 'database')?.response?.diagnosis || {},
      issues: consolidated.issues.filter(i => i.type === 'database' || i.component === 'database'),
      context: consolidated.agentAnalyses.find(a => a.agentType === 'database')?.response || {}
    }
  });
}

if (actionsByAgent.developer.length > 0) {
  resolverCalls.push({
    resolverType: 'developer',
    resolverName: 'Resolutor de Desenvolvimento',
    endpoint: $env.WORKFLOW_RESOLUTOR_DEV_URL || 'http://localhost:5678/webhook/resolutor-dev',
    payload: {
      troubleshootingSessionId: consolidated.sessionId,
      sessionId: `resolver_${Date.now()}_developer`,
      timestamp: new Date().toISOString(),
      actionPlan: actionsByAgent.developer,
      diagnosis: consolidated.agentAnalyses.find(a => a.agentType === 'developer')?.response?.diagnosis || {},
      issues: consolidated.issues.filter(i => i.type === 'frontend' || i.component === 'frontend'),
      context: consolidated.agentAnalyses.find(a => a.agentType === 'developer')?.response || {}
    }
  });
}

return resolverCalls.map(call => ({ json: call }));

// Processar resposta dos resolutores
const resolverCall = $('Processar Chamadas Resolutores').item.json;
const resolverResponse = $input.item.json;

// Processar resposta
let response = {};
if (resolverResponse.body) {
  response = typeof resolverResponse.body === 'string' 
    ? JSON.parse(resolverResponse.body) 
    : resolverResponse.body;
} else {
  response = resolverResponse;
}

return [{
  json: {
    resolverType: resolverCall.resolverType,
    resolverName: resolverCall.resolverName,
    troubleshootingSessionId: resolverCall.payload.troubleshootingSessionId,
    response: response,
    status: resolverResponse.statusCode === 200 ? 'success' : 'error',
    timestamp: new Date().toISOString()
  }
}];

// Agregar respostas dos resolutores
const resolverResponses = $input.all();
const consolidated = $('Consolidar Resultados').item.json;
const savedReport = $('Salvar Relatório Consolidado').item.json[0];

const resolversSummary = {
  totalResolversCalled: resolverResponses.length,
  resolversWithPlans: resolverResponses.filter(r => r.json.response && r.json.response.executionPlan).length,
  resolvers: resolverResponses.map(r => r.json)
};

return [{
  json: {
    troubleshooting: consolidated,
    reportId: savedReport.id,
    resolvers: resolversSummary,
    readyForNotification: true
  }
}];
